//! RESEARCH-ONLY. Towns in the panel (research/mechanisms/town-authority.md): the town-authority
//! model derived from the engine sources (tools/research/town-model/town_model.json, generated by
//! derive.py, never edited by hand) and, when a game is connected, every live town with one
//! company's rating and the advice of town_lib.rhai's `advice(town, tolerance)`. The advice runs in
//! this process in a Rhai engine that imports the panel's script library, so the logic lives in one
//! place: the scripts, the bot's model and this page read the same rules. The routes are rows of the
//! panel's route table, so OpenAPI, Swagger UI, GraphQL on the hub and Rhai derive them.

use std::path::{Path, PathBuf};
use std::sync::atomic::Ordering;
use std::sync::Arc;

use serde_json::{json, Map, Value};

use crate::panel::{Game, Input};
use crate::panel_results::repo;

/// The generated model, read at runtime as the real-world module reads its fixtures.
pub fn model_path() -> PathBuf {
    repo().join("tools/research/town-model/town_model.json")
}

/// The fields a live town record may carry beyond id, name, tile, x, y and population; each is
/// optional, the engine adds them as it grows (openttd://towns, ResourceTowns).
pub const OPTIONAL_FIELDS: &[&str] = &["active_stations", "idle_stations", "statue", "exclusivity", "exclusive_months",
                                       "unwanted_months", "fund_buildings_months", "growth_rate"];

/// The names town_lib.rhai uses for difficulty.town_council_tolerance, by the setting's value
/// (src/town.h TOWN_COUNCIL_LENIENT .. TOWN_COUNCIL_PERMISSIVE).
pub const TOLERANCES: [&str; 4] = ["lenient", "tolerant", "hostile", "permissive"];

/// The tolerance in the console's answer to `setting difficulty.town_council_tolerance`
/// ("Current value for 'difficulty.town_council_tolerance' is '2' (min: 0, ...)"), as a name.
pub fn tolerance_of(line: &str) -> Option<&'static str> {
    let rest = &line[line.find("town_council_tolerance")? + "town_council_tolerance".len()..];
    let rest = rest.strip_prefix('\'').unwrap_or(rest).strip_prefix(" is ")?;
    let rest = rest.strip_prefix('\'').unwrap_or(rest);
    let n = rest.chars().take_while(char::is_ascii_digit).count();
    if n > 0 {
        return rest[..n].parse::<usize>().ok().and_then(|i| TOLERANCES.get(i).copied());
    }
    TOLERANCES.iter().copied().find(|t| rest.to_ascii_lowercase().starts_with(t))
}

/// One company's value of a field the town may store per company: a plain value as it is, an
/// object keyed by company id, or (for `statue`) a list of the companies that have one.
fn for_company(field: &str, v: &Value, company: Option<i64>) -> Value {
    match (v, company) {
        (Value::Object(m), Some(c)) => m.get(&c.to_string()).cloned().unwrap_or(Value::Null),
        (Value::Object(_), None) => Value::Null,
        (Value::Array(a), Some(c)) if field == "statue" => json!(a.iter().any(|x| x.as_i64() == Some(c))),
        (Value::Array(_), _) if field == "statue" => Value::Null,
        _ => v.clone(),
    }
}

/// One company's entry of a town's per-company list: `companies` as the engine publishes it
/// (src/prismatic_mcp/prismatic_mcp_server.cpp ResourceTowns: company, rating, has_rating, statue,
/// unwanted_months, active_stations, idle_stations), else an older `ratings` list.
fn company_entry(town: &Value, company: Option<i64>) -> Option<Value> {
    let c = company?;
    ["companies", "ratings"].iter().find_map(|k| town[*k].as_array()?.iter().find(|x| x["company"].as_i64() == Some(c)).cloned())
}

/// The record town_lib's `advice` reads for one company: its rating and band, its own per-company
/// fields from the town's company list, and every other optional field the town has.
pub fn town_record(town: &Value, company: Option<i64>) -> Value {
    let mut r = Map::new();
    for f in OPTIONAL_FIELDS {
        if let Some(v) = town.get(*f).filter(|v| !v.is_null()) {
            let v = for_company(f, v, company);
            if !v.is_null() { r.insert((*f).into(), v); }
        }
    }
    if let Some(m) = company_entry(town, company) {
        if m["rating"].is_i64() { r.insert("rating".into(), m["rating"].clone()); }
        if m["band"].is_i64() { r.insert("band".into(), m["band"].clone()); }
        for f in ["statue", "unwanted_months", "active_stations", "idle_stations"] {
            if let Some(v) = m.get(f).filter(|v| !v.is_null()) { r.insert(f.into(), v.clone()); }
        }
    }
    Value::Object(r)
}

/// Every company id that has a rating in any town (has_rating, or any entry of an older `ratings`
/// list), in order.
pub fn rated_companies(towns: &[Value]) -> Vec<i64> {
    let mut ids: Vec<i64> = towns.iter().flat_map(|t| {
        let mut v: Vec<Value> = t["companies"].as_array().cloned().unwrap_or_default().into_iter()
            .filter(|x| x["has_rating"].as_bool().unwrap_or(false)).collect();
        v.extend(t["ratings"].as_array().cloned().unwrap_or_default());
        v
    }).filter_map(|x| x["company"].as_i64()).collect();
    ids.sort();
    ids.dedup();
    ids
}

const ADVICE_SCRIPT: &str = r#"
import "town_lib" as tl;
let out = [];
for t in records {
    let band = ();
    if type_of(t.rating) == "i64" { band = tl::band_of(t.rating); }
    else if type_of(t.band) == "i64" { band = tl::band_from_enum(t.band); }
    let name = ();
    if band != () { name = band.name; }
    out.push(#{ band: name, floor: tl::rating_floor(t), advice: tl::advice(t, tolerance) });
}
out
"#;

/// town_lib.rhai's band and advice for every record, run in an engine that imports the script
/// library at `lib` (the panel passes rhai_host::rhai_dir(): $MCP_RHAI_PATH, else
/// tools/research/mcp-panel/rhai): one answer per record.
pub fn advise(lib: &Path, records: &[Value], tolerance: &str) -> Result<Vec<Value>, String> {
    let mut engine = rhai::Engine::new();
    engine.set_module_resolver(rhai::module_resolvers::FileModuleResolver::new_with_path(lib));
    let mut scope = rhai::Scope::new();
    scope.push("records", rhai::serde::to_dynamic(records).map_err(|e| e.to_string())?);
    scope.push("tolerance", tolerance.to_string());
    let out = engine.eval_with_scope::<rhai::Dynamic>(&mut scope, ADVICE_SCRIPT).map_err(|e| format!("town_lib: {e}"))?;
    let v: Value = rhai::serde::from_dynamic(&out).map_err(|e| e.to_string())?;
    Ok(v.as_array().cloned().unwrap_or_default())
}

/// The live answer from openttd://towns' payload (`{"towns": [...]}`), for one company and
/// tolerance: each town with that company's record, band and advice, from the library at `lib`.
/// Pure, so a test runs it.
pub fn live_from(lib: &Path, towns_payload: &Value, company: Option<i64>, tolerance: &str) -> Value {
    let towns: Vec<Value> = towns_payload["towns"].as_array().cloned().unwrap_or_default();
    let companies = rated_companies(&towns);
    let company = company.or_else(|| companies.first().copied());
    let records: Vec<Value> = towns.iter().map(|t| town_record(t, company)).collect();
    let present: Vec<&str> = OPTIONAL_FIELDS.iter().copied().chain(["companies", "ratings"])
        .filter(|f| towns.iter().any(|t| t.get(*f).is_some_and(|v| !v.is_null()))).collect();
    let (advised, error) = match advise(lib, &records, tolerance) {
        Ok(a) => (a, None),
        Err(e) => (Vec::new(), Some(e)),
    };
    let out: Vec<Value> = towns.iter().zip(&records).enumerate().map(|(i, (t, r))| {
        let a = advised.get(i).cloned().unwrap_or(Value::Null);
        json!({"id": t["id"], "name": t["name"], "tile": t["tile"], "x": t["x"], "y": t["y"], "population": t["population"],
               "rating": r.get("rating"), "band": a["band"], "rating_floor": a["floor"], "record": r,
               "advice": a.get("advice").cloned().unwrap_or(json!([]))})
    }).collect();
    json!({"company": company, "rated_companies": companies, "tolerance": tolerance, "count": out.len(), "towns": out,
           "fields": present, "advice_error": error, "reason": Value::Null})
}

pub fn h_model(_: &Arc<Game>, _: &Input) -> Result<(u16, Value), String> {
    let p = model_path();
    let text = match std::fs::read_to_string(&p) {
        Ok(t) => t,
        Err(e) => return Ok((404, json!({"error": format!("{}: {e}; run tools/research/town-model/derive.py", p.display())}))),
    };
    serde_json::from_str::<Value>(&text).map(|v| (200, v)).map_err(|e| format!("{}: {e}", p.display()))
}

/// No game, no towns: an answer the page shows, never an error.
fn empty(company: Option<i64>, tolerance: &str, reason: String) -> (u16, Value) {
    (200, json!({"company": company, "rated_companies": [], "companies": [], "tolerance": tolerance, "count": 0, "towns": [],
                 "fields": [], "advice_error": null, "reason": reason}))
}

pub fn h_live(g: &Arc<Game>, i: &Input) -> Result<(u16, Value), String> {
    let company = match i.query.get("company").filter(|s| !s.is_empty()) {
        None => None,
        Some(s) => match s.parse::<i64>() {
            Ok(c) if (0..=255).contains(&c) => Some(c),
            _ => return Ok((400, json!({"error": "company: a company id, e.g. 0"}))),
        },
    };
    if !g.mcp_up.load(Ordering::SeqCst) {
        return Ok(empty(company, "lenient", "no game connected: the MCP server is not up".into()));
    }
    let payload = match g.resource("openttd://towns") {
        Ok(v) if v.get("error").is_none() => match v { Value::Object(mut m) if m.contains_key("data") => m.remove("data").unwrap_or(Value::Null), o => o },
        Ok(v) => return Ok(empty(company, "lenient", format!("openttd://towns: {}", v["error"]))),
        Err(e) => return Ok(empty(company, "lenient", format!("openttd://towns: {e}"))),
    };
    // The tolerance from the game's console when the server runs, else the setting's default.
    let read = if g.server_running() {
        let mark = g.log_seq();
        g.console("setting difficulty.town_council_tolerance").ok().and_then(|_| {
            std::thread::sleep(std::time::Duration::from_millis(600));
            g.log_after(mark).iter().find_map(|l| tolerance_of(l))
        })
    } else {
        None
    };
    let tolerance = read.unwrap_or("lenient");
    let mut out = live_from(&crate::rhai_host::rhai_dir(), &payload, company, tolerance);
    out["tolerance_source"] = json!(if read.is_some() { "console: setting difficulty.town_council_tolerance" }
                                    else { "default: lenient (the console gave none)" });
    let cs = g.resource("openttd://companies").ok().map(|v| v.get("data").cloned().unwrap_or(v));
    out["companies"] = json!(cs.and_then(|c| c["companies"].as_array().cloned()).unwrap_or_default().iter()
        .map(|c| json!({"id": c["id"], "name": c["name"], "is_ai": c["is_ai"]})).collect::<Vec<_>>());
    Ok((200, out))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_model_route_serves_the_generated_model_with_sources() {
        let m: Value = serde_json::from_str(&std::fs::read_to_string(model_path()).unwrap()).unwrap();
        assert_eq!(m["schema"], "town-model/v1");
        for part in ["effects", "gates", "actions", "links", "relations"] {
            let rows = m[part].as_array().unwrap();
            assert!(!rows.is_empty(), "{part}");
            assert!(rows.iter().all(|r| r["source"].as_str().is_some_and(|s| s.contains(':'))), "{part}: every rule has path:line");
        }
    }

    #[test]
    fn the_tolerance_is_read_from_the_console() {
        assert_eq!(tolerance_of("Current value for 'difficulty.town_council_tolerance' is '2' (min: 0, max: 3, def: 0)."), Some("hostile"));
        assert_eq!(tolerance_of("Current value for 'difficulty.town_council_tolerance' is '0' (min: 0)"), Some("lenient"));
        assert_eq!(tolerance_of("Current value for 'difficulty.town_council_tolerance' is '9'"), None);
        assert_eq!(tolerance_of("Current value for 'difficulty.max_loan' is '300000'"), None);
    }

    #[test]
    fn a_record_reads_the_engines_company_list() {
        let t = json!({"id": 1, "growth_rate": 900, "companies": [
            {"company": 0, "rating": -260, "has_rating": true, "statue": false, "unwanted_months": 0, "active_stations": 0, "idle_stations": 2},
            {"company": 1, "rating": 500, "has_rating": false, "statue": true, "unwanted_months": 0, "active_stations": 1, "idle_stations": 0}]});
        assert_eq!(town_record(&t, Some(0)), json!({"growth_rate": 900, "rating": -260, "statue": false, "unwanted_months": 0,
                                                    "active_stations": 0, "idle_stations": 2}));
        assert_eq!(town_record(&t, Some(1))["statue"], json!(true));
        assert_eq!(rated_companies(&[t]), vec![0]);
    }

    #[test]
    fn a_record_takes_one_companys_rating_and_the_optional_fields() {
        let t = json!({"id": 1, "ratings": [{"company": 0, "rating": -260, "band": 2}, {"company": 1, "rating": 700, "band": 7}],
                       "active_stations": {"0": 0, "1": 3}, "idle_stations": 1, "statue": [1], "growth_rate": null});
        assert_eq!(town_record(&t, Some(0)), json!({"rating": -260, "band": 2, "active_stations": 0, "idle_stations": 1, "statue": false}));
        assert_eq!(town_record(&t, Some(1))["statue"], json!(true));
        assert_eq!(town_record(&json!({"id": 2}), Some(0)), json!({}));
        assert_eq!(rated_companies(&[t]), vec![0, 1]);
    }

    /// The route's advice is town_lib's: a refusing town gets the remedies of the town_lib test, a
    /// town of today's openttd://towns (no ratings) is read at the initial rating.
    #[test]
    fn live_towns_get_town_libs_advice() {
        let payload = json!({"towns": [
            {"id": 0, "name": "Aville", "tile": 10, "x": 10, "y": 0, "population": 900,
             "ratings": [{"company": 0, "rating": -260, "band": 2}], "active_stations": 0, "idle_stations": 1},
            {"id": 1, "name": "Btown", "tile": 20, "x": 20, "y": 0, "population": 400}]});
        // The checkout's library, not $MCP_RHAI_PATH: another test points that at a scratch directory.
        let lib = Path::new(concat!(env!("CARGO_MANIFEST_DIR"), "/../mcp-panel/rhai"));
        let out = live_from(lib, &payload, None, "lenient");
        assert_eq!(out["company"], 0, "the first rated company when none is asked for");
        assert_eq!(out["advice_error"], Value::Null);
        let a = &out["towns"][0];
        assert_eq!(a["band"], "TOWN_RATING_VERY_POOR");
        let whats: Vec<&str> = a["advice"].as_array().unwrap().iter().map(|x| x["what"].as_str().unwrap()).collect();
        assert_eq!(&whats[..2], ["plant 9 tree tiles near the town", "serve or remove the idle stations"]);
        assert_eq!(a["advice"][0]["source"], "src/tree_cmd.cpp CmdPlantTree");
        let b = &out["towns"][1];
        assert_eq!(b["rating"], Value::Null);
        assert_eq!(b["rating_floor"], 500);
        assert_eq!(live_from(lib, &payload, Some(0), "permissive")["towns"][1]["advice"][0]["what"], "build freely");
        assert_eq!(out["fields"], json!(["active_stations", "idle_stations", "ratings"]));
    }
}
